// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;
    bool public firstSet;
    uint public oldMinSum;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 min1, uint256 min2) internal {
        vm.assume(min1 != min2);
        try c.SetMinSum(min1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.MinSum() returns (uint256 __r) { oldMinSum = __r; } catch { return; }
        try c.SetMinSum(min2) {} catch { return; }
        uint256 newMinSum;
        try c.MinSum() returns (uint256 __r) { newMinSum = __r; } catch { return; }
        assertTrue(oldMinSum == newMinSum);
    }

    function testFuzz_test(uint256 min1, uint256 min2) public {
        _test(min1, min2);
    }

    receive() external payable {}
}
